package mz.gov.mogovolas.expedientes.controller;
import mz.gov.mogovolas.expedientes.entity.*; import mz.gov.mogovolas.expedientes.repository.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAuthority('UTILIZADOR_GERIR')") public class AdminController {final UtilizadorRepository u;final PapelRepository p;final SectorRepository s;final PermissaoRepository pm;final PasswordEncoder enc; public AdminController(UtilizadorRepository u,PapelRepository p,SectorRepository s,PermissaoRepository pm,PasswordEncoder e){this.u=u;this.p=p;this.s=s;this.pm=pm;enc=e;} @PostMapping("/utilizadores") public Utilizador user(@RequestBody Map<String,Object>x){Utilizador z=new Utilizador();z.setNome((String)x.get("nome"));z.setUsername((String)x.get("username"));z.setEmail((String)x.get("email"));z.setPassword(enc.encode((String)x.get("password")));z.setActivo(Boolean.parseBoolean(String.valueOf(x.getOrDefault("activo",true))));z.setSector(s.findById(Long.valueOf(String.valueOf(x.get("sectorId")))).orElseThrow());Object roles=x.get("papelIds");if(roles instanceof List<?> l)for(Object id:l)z.getPapeis().add(p.findById(Long.valueOf(String.valueOf(id))).orElseThrow());return u.save(z);} @PutMapping("/utilizadores/{id}") public Utilizador toggle(@PathVariable Long id,@RequestParam boolean activo){Utilizador z=u.findById(id).orElseThrow();z.setActivo(activo);return u.save(z);} @PostMapping("/sectores") public Sector sector(@RequestBody Sector x){return s.save(x);} @PutMapping("/sectores/{id}") public Sector sector(@PathVariable Long id,@RequestBody Sector x){Sector z=s.findById(id).orElseThrow();z.setNome(x.getNome());z.setDescricao(x.getDescricao());return s.save(z);} @DeleteMapping("/sectores/{id}") public void delSector(@PathVariable Long id){s.deleteById(id);} @PostMapping("/papeis") public Papel papel(@RequestBody Papel x){return p.save(x);} @PutMapping("/papeis/{id}/permissoes") public Papel rolePerm(@PathVariable Long id,@RequestBody List<Long> ids){Papel r=p.findById(id).orElseThrow();r.getPermissoes().clear();ids.forEach(x->r.getPermissoes().add(pm.findById(x).orElseThrow()));return p.save(r);} }
